// Ссылки на странице /about тест не нажимает; браузер закрывается только его кнопкой закрытия.
import { by } from '../../lib/appium.mjs';
import { onHome, tab, checkAboutPage, closeInAppBrowser } from '../../lib/banci.mjs';

export const name = '«בית» → карточка «איך Banci עובדת» внизу → /about во встроенном браузере → закрыть #94e4f3 @iphone @app @prod-safe';

const CARD = 'איך Banci עובדת';

export default async function (app) {
  // 5. «בית» → прокрутить вниз до карточки «איך Banci עובדת».
  await onHome(app);
  const card = await app.scrollTo(by.begins(CARD), { max: 10, what: `карточка «${CARD}» внизу «בית»` });

  // Тап → та же страница /about во встроенном браузере.
  await card.click();
  await checkAboutPage(app);

  // Закрыть → снова «בית» с карточкой.
  await closeInAppBrowser(app);
  await app.waitFor(tab('בית'), { what: 'таб-бар «בית» после закрытия браузера' });
  await app.scrollTo(by.begins(CARD), { max: 10, what: `после закрытия — «בית» с карточкой «${CARD}»` });
}
